  const suffix = `${formatCount(risky)} of ${formatCount(total)} accounts critical or storm warning`
  if (row.no_data) {
    return `${row.district_name}, no demographic data, ${suffix}`
  }
  return `${row.district_name}, ${suffix}`
}

